from datetime import date, timedelta

# Excel counts days from 1899-12-30 because it treats 1900 as a leap year: https://learn.microsoft.com/en-us/troubleshoot/microsoft-365-apps/excel/wrongly-assumes-1900-is-leap-year
EXCEL_EPOCH = date(1899, 12, 30)


def from_serial(serial: int) -> date:
    return EXCEL_EPOCH + timedelta(days=serial)
